

# This file was *autogenerated* from the file check_02_V2_as_kronecker_power.sage
from sage.all_cmdline import *   # import sage library

_sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_3 = Integer(3); _sage_const_4 = Integer(4); _sage_const_5 = Integer(5); _sage_const_0p4 = RealNumber('0.4'); _sage_const_0p9 = RealNumber('0.9'); _sage_const_0p25 = RealNumber('0.25'); _sage_const_1p3 = RealNumber('1.3'); _sage_const_0p4406868 = RealNumber('0.4406868'); _sage_const_1p0 = RealNumber('1.0')# <def_transfer_matrix>: V_2 を「2×2 転送行列のクロネッカー積」として独立に構成して突き合わせる
#
# check_01_transfer_matrix_sanity.sage は V_1, V_2 の全成分を定義式 (V_2)_{μ,μ'} = exp(Σ_j J μ(j)μ'(j))
# からそのまま再計算して照合している。ここではそれとは別経路として、
#   t := ((e^J, e^{-J}), (e^{-J}, e^J))   （1 サイト分の 2×2 転送行列）
# の N 重クロネッカー積 t^{⊠N} が V_2 に一致することを見る。
# 添字の対応は「μ(j) = -1 → ビット 0, μ(j) = +1 → ビット 1、j が上位から下位へ」であり、
# これは _prelude.sage の transfer_matrices が既定で使う itertools.product([-1,1], repeat=N) の順に一致する。
# 定義式の和 Σ_j が積 Π_j へ分解すること（サイトごとに独立であること）を、
# 成分ごとの再計算ではなくクロネッカー積という構成レベルで確かめる経路になっている。

import os
_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in dir() else "."
load(os.path.join(_dir, "../../_shared/operators.sage"))
import numpy as np
import itertools
load(os.path.join(_dir, "_prelude.sage"))

rep = CheckReport("def_transfer_matrix: V_2 = t^(⊠N)（2×2 転送行列のクロネッカー積）")

for N in [_sage_const_1 , _sage_const_2 , _sage_const_3 , _sage_const_4 , _sage_const_5 ]:
    for (J, Jp) in [(_sage_const_0p4 , _sage_const_0p9 ), (_sage_const_0p9 , _sage_const_0p4 ), (_sage_const_0p25 , _sage_const_1p3 ), (_sage_const_0p4406868 , _sage_const_0p4406868 )]:
        V1, V2 = transfer_matrices(J, Jp, N)

        t = np.array([[np.exp(J), np.exp(-J)], [np.exp(-J), np.exp(J)]], dtype=float)
        V2kron = np.array([[_sage_const_1p0 ]])
        for _ in range(N):
            V2kron = np.kron(V2kron, t)
        rep.close(V2, V2kron, f"N={N} J={J}: V_2 = t^(⊠N)")

        # V_1 は同じ形には分解しない（行内結合が隣接サイトを結ぶため）。
        # 対角成分だけを 1 次元 Ising 環のエネルギーから直接組み上げて照合する。
        mus = list(itertools.product([-_sage_const_1 , _sage_const_1 ], repeat=N))
        rep.truth(len(mus) == _sage_const_2  ** N, f"N={N}: |M| = 2^N = {_sage_const_2  ** N}")
        diag_direct = np.array([
            float(np.exp(sum(Jp * mu[j] * mu[(j + _sage_const_1 ) % N] for j in range(N))))
            for mu in mus
        ])
        rep.close(np.diag(V1), diag_direct, f"N={N} Jp={Jp}: V_1 の対角成分（1 次元 Ising 環のエネルギー）")
    print("  N=%d : |M|=%d, V_2 = t^(⊠N) を全パラメータで確認" % (N, _sage_const_2  ** N))

rep.finish()

